    ///   - sourceId: Exact source ID.
    ///   - topPriority: Exact highest open priority, from 0 to 4.
    ///   - includeClosed: Include epics with no non-closed tasks; defaults to false.
    ///   - limit: Maximum epics; defaults to 50, capped at 100.
    ///   - afterCursor: Opaque forward cursor from the preceding page.
    /// - Returns: Successful response
    public func taskEpics(org: String, sourceScope: String? = nil, sourceType: String? = nil, sourceId: String? = nil, topPriority: Int? = nil, includeClosed: Bool? = nil, limit: Int? = nil, afterCursor: String? = nil) async throws -> OrgTaskEpicsResponse {
        var query: [(String, String)] = []
        if let sourceScope = sourceScope {
            query.append(("source_scope", sourceScope))
        }
        if let sourceType = sourceType {
            query.append(("source_type", sourceType))
        }
        if let sourceId = sourceId {
            query.append(("source_id", sourceId))
        }
        if let topPriority = topPriority {
            query.append(("top_priority", String(topPriority)))
        }
        if let includeClosed = includeClosed {
            query.append(("include_closed", includeClosed ? "true" : "false"))
        }
        if let limit = limit {
            query.append(("limit", String(limit)))
        }
        if let afterCursor = afterCursor {
            query.append(("after_cursor", afterCursor))
        }
        return try await http.request("/api/v1/orgs/\(org)/task_epics", query: query)
    }
}
